import Foundation

// Reference values were generated by the pinned, unmodified upstream timing functions.
@main
struct PlaybackRateTest {
  static func main() throws {
    let root =
      try JSONSerialization.jsonObject(
        with: Data(contentsOf: URL(fileURLWithPath: CommandLine.arguments[1]))) as! [String: Any]
    let cases = root["cases"] as! [[String: Any]]
    var samples = 0
    for item in cases {
      let rate = try HTMLVideoPlaybackRate(
        constant: item["constant"] as! Double, points: item["points"] as! [[String: Any]])
      let restored = try HTMLVideoPlaybackRate(dictionary: rate.dictionary)
      for sample in item["samples"] as! [[Double]] {
        let source = rate.sourceTime(at: sample[0])
        precondition(abs(source - sample[1]) < 1e-10, "\(item["name"]!): \(sample), got \(source)")
        precondition(abs(rate.timelineTime(at: source) - sample[2]) < 1e-10)
        precondition(abs(restored.sourceTime(at: sample[0]) - source) < 1e-10)
        samples += 1
      }
    }
    print(
      "Verified \(samples) source-time, inverse-time, and serialized-table samples against pinned HyperFrames."
    )
  }
}
